+        width: 100%;
+        padding: 20px 22px;
+        border: 0;
+        text-align: left;
+        color: var(--text);
+        background: transparent;
+        cursor: pointer;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 18px;
+        font: inherit;
