+        flex: 0 0 auto;
+        width: 28px;
+        height: 28px;
+        border-radius: 999px;
+        display: grid;
+        place-items: center;
+        color: #f5f7ff;
+        background: linear-gradient(135deg, rgba(139, 92, 246, 0.9), rgba(34, 211, 238, 0.75));
+        transition: transform 180ms ease;
+      }
+
+      .example.open .chevron {
+        transform: rotate(180deg);
+      }
+
+      .details {
+        display: none;
+        padding: 0 22px 22px;
+        color: var(--muted);
+        line-height: 1.75;
+      }
+
+      .example.open .details {
+        display: block;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details strong {
+        color: #f5f7ff;
+      }
+
+      @media (max-width: 640px) {
+        .app {
+          width: min(100% - 20px, 920px);
+          padding: 34px 0 42px;
+        }
+
+        .question {
+          padding: 18px 16px;
+        }
+
+        .details {
+          padding: 0 16px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main id="app" class="app"></main>
+
+    <script>
+      const faqs = [
+        {
+          question: "Why do cats purr?",
+          answer:
+            "Cats purr for comfort, communication, and sometimes self-soothing. You will often hear it when they feel safe, but they may also purr when they are stressed or unwell.",
+        },
+        {
+          question: "Do cats really land on their feet?",
+          answer:
+            "Cats have a strong righting reflex and flexible bodies that help them reorient mid-air. It is a useful survival skill, but falls can still injure them, so high places are not always safe.",
+        },
+        {
+          question: "Why do cats knead blankets or laps?",
+          answer:
+            "Kneading is usually a leftover kitten behavior tied to nursing. Adult cats often do it when they are relaxed, marking a favorite spot with scent glands in their paws.",
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer:
+            "Most cats sleep between 12 and 16 hours a day, and some even more. Their energy tends to come in short bursts, especially around dawn and dusk.",
+        },
+        {
+          question: "What is the best way to keep indoor cats happy?",
+          answer:
+            "Give them vertical space, scratching posts, puzzle feeders, toys, and predictable routines. A window perch and daily playtime can make a big difference too.",
+        },
+      ];
+
+      function FAQItem(item, index) {
+        const id = `faq-${index}`;
+        return `
+          <div class="example">
+            <button
+              class="question"
+              type="button"
+              aria-expanded="false"
+              aria-controls="${id}"
+            >
+              <span class="question-title">${item.question}</span>
+              <span class="chevron" aria-hidden="true">⌄</span>
+            </button>
+            <div class="details" id="${id}">
+              <p>${item.answer}</p>
+            </div>
+          </div>
+        `;
+      }
+
+      function FAQPage(items) {
+        return `
+          <section class="hero">
+            <div class="eyebrow">Cat FAQ</div>
+            <h1>Curious about cats?</h1>
+            <p class="subtitle">
+              Tap a question to reveal the answer. Each item starts collapsed for a clean,
+              focused reading experience.
+            </p>
+          </section>
+          <section class="faq" aria-label="Frequently asked questions">
+            ${items.map(FAQItem).join("")}
+          </section>
+        `;
+      }
+
+      document.getElementById("app").innerHTML = FAQPage(faqs);
+
+      document.querySelectorAll(".example").forEach((example) => {
+        const button = example.querySelector(".question");
+        const details = example.querySelector(".details");
+
+        button.addEventListener("click", () => {
+          const open = example.classList.toggle("open");
+          button.setAttribute("aria-expanded", String(open));
+          details.hidden = !open;
+        });
+
+        details.hidden = true;
+      });
+    </script>
+  </body>
+</html>
*** End Patch
