        max-width: 60ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 16px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        overflow: hidden;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.84));
